-- rc-ev.com check (user, 2026-11-20): the dealer follows rc-ev.com, so its numbers win.
--   A. Spec sheets for the five models that had none (EC31, EC31L, C5 Drone, EC75, R5), built by
--      scripts/specs/import-rcev.mts from the rc-ev.com product pages in our own format (labels, Mongolian
--      values, abbreviation + explanation). Prices, the manufacturer warranty and colours are left out.
--      EC75 / R5: cargo and passenger in one sheet; configuration names start with «Ачааны · » / «Зорчигчийн · »
--      and the page shows the side chosen in the hero switch (ConfigPicker). Only the 58.24 kWh (2C) trims.
--      Written only where the model has no sheet yet, so nothing typed in /admin is overwritten.
--   B. Values on existing sheets where rc-ev.com differs (scratchpad compare, 2026-11-20).
--   C. Card / hero numbers (models.stats, range) that follow from A and B. EC75 showed the EC75 Pro figures.
--
-- Run by hand in Supabase → SQL Editor AFTER the code from feat/model-page-b is deployed (READY) and after
-- 0010–0013. Safe to run twice. The Google Sheet «Ruichi specs» should get the B values too.

begin;

create or replace function pg_temp.per_config(specs jsonb, val text) returns jsonb language sql immutable as $$
  select coalesce(jsonb_agg(to_jsonb(val)), '[]'::jsonb) from generate_series(1, jsonb_array_length(specs->'configs'))
$$;
create or replace function pg_temp.set_value(specs jsonb, key text, val text) returns jsonb language sql immutable as $$
  select jsonb_set(specs, array['values', key], pg_temp.per_config(specs, val), true)
$$;

-- ---------------------------------------------------------------------------
-- A. New sheets
-- ---------------------------------------------------------------------------

