-- ---------------------------------------------------------------------------
-- B. rc-ev.com numbers on existing sheets
-- ---------------------------------------------------------------------------

-- EC35II (5-seat): 38.4 kWh, 282 km (CLTC), 200 N·m, 2.98 m³ cargo (was 38.64 / 274 / 220 / 3.1).
update public.models set specs = pg_temp.set_value(pg_temp.set_value(pg_temp.set_value(pg_temp.set_value(specs, 'battery_kwh', '38.4'), 'range', '282'), 'torque', '200'), 'cargo_volume', '2.98')
where slug = 'ec35' and specs is not null;

-- EC75 Pro / R5 Pro passenger: 430 km with 61.94 kWh (was 415 / 420). EC75 Pro passenger: 6 or 9 seats (was 6 / 9 / 11 / 14).
-- R5 Pro cargo: top speed 100 km/h (was 90).
update public.models set specs = pg_temp.set_value(specs, 'range', '430') where slug in ('ec75pro-passenger', 'r5pro-passenger') and specs is not null;
update public.models set specs = pg_temp.set_value(specs, 'seats', '6 / 9') where slug = 'ec75pro-passenger' and specs is not null;
update public.models set specs = pg_temp.set_value(specs, 'top_speed', '100') where slug = 'r5pro-cargo' and specs is not null;

-- C9 (120 kWh): curb weight 3,420 kg with side doors, 3,360 kg with the cage body.
update public.models set specs = pg_temp.set_value(specs, 'curb_weight', '3420 (хажуу хаалгатай), 3360 (торон)') where slug = 'c9' and specs is not null;

-- ---------------------------------------------------------------------------
-- C. Card and hero numbers
-- ---------------------------------------------------------------------------

update public.models set range = '282 км', stats = $json$[{"value":"282","unit":"км","label":"Туулах зай (CLTC)"},{"value":"38.4","unit":"кВт·ц","label":"Батерейн багтаамж"},{"value":"60","unit":"кВт","label":"Моторын оргил чадал"},{"value":"2.98","unit":"м³","label":"Ачааны багтаамж"}]$json$::jsonb
where slug = 'ec35';

update public.models set range = '430 км', seats = '6–9 суудал', stats = $json$[{"value":"430","unit":"км","label":"Туулах зай (CLTC)"},{"value":"61.94","unit":"кВт·ц","label":"Батерейн багтаамж"},{"value":"130","unit":"кВт","label":"Моторын оргил чадал"},{"value":"6–9","unit":"суудал","label":"Суудлын тоо"}]$json$::jsonb
where slug = 'ec75pro-passenger';

update public.models set range = '430 км', stats = $json$[{"value":"430","unit":"км","label":"Туулах зай (CLTC)"},{"value":"61.94","unit":"кВт·ц","label":"Батерейн багтаамж"},{"value":"130","unit":"кВт","label":"Моторын оргил чадал"},{"value":"6–9","unit":"суудал","label":"Суудлын тоо"}]$json$::jsonb
where slug = 'r5pro-passenger';

-- EC75 (not Pro): the same figures as R5 — 58.24 kWh, 70 kW cargo / 100 kW passenger, 401 / 403 km, 6 or 9 seats.
update public.models set range = '401–403 км', seats_passenger = '6–9 суудал', stats = $json$[{"value":{"cargo":"401","passenger":"403"},"unit":"км","label":"Туулах зай (CLTC)","note":1},{"value":"18","unit":"мин","label":"Хурдан цэнэглэлт 20–80%"},{"value":{"cargo":"70","passenger":"100"},"unit":"кВт","label":"Моторын оргил чадал"},{"value":{"cargo":"7.7","passenger":"6–9"},"unit":{"cargo":"м³","passenger":"суудал"},"label":{"cargo":"Ачааны багтаамж","passenger":"Суудлын тоо"}}]$json$::jsonb
where slug = 'ec75';

commit;

